import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Timetable() {
  const [classes, setClasses] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:8081/api/timetable')
      .then(res => setClasses(res.data))
      .catch(err => console.error(err));
  }, []);

  return (
    <div style={{ padding: '50px', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      <h2 style={{ textAlign: 'center' }}>Official Class Timetable</h2>
      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px', backgroundColor: 'white' }}>
        <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
          <tr>
            <th style={{ padding: '15px' }}>Day</th>
            <th style={{ padding: '15px' }}>Grade</th>
            <th style={{ padding: '15px' }}>Subject</th>
            <th style={{ padding: '15px' }}>Time</th>
            <th style={{ padding: '15px' }}>Teacher</th>
          </tr>
        </thead>
        <tbody>
          {classes.map(c => (
            <tr key={c.id} style={{ borderBottom: '1px solid #ddd', textAlign: 'center' }}>
              <td style={{ padding: '15px' }}>{c.day}</td>
              <td style={{ padding: '15px' }}>{c.grade}</td>
              <td style={{ padding: '15px' }}>{c.subject}</td>
              <td style={{ padding: '15px' }}>{c.time_slot}</td>
              <td style={{ padding: '15px' }}>{c.teacher}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
